import{_ as a,o as n,c as e,a0 as s}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"Agent 的经济性分析","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/01_基础概念/06_Agent的经济性分析.md","filePath":"06-agent/01_基础概念/06_Agent的经济性分析.md"}'),o={name:"06-agent/01_基础概念/06_Agent的经济性分析.md"};function r(i,t,l,d,g,p){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="agent-的经济性分析" tabindex="-1">Agent 的经济性分析 <a class="header-anchor" href="#agent-的经济性分析" aria-label="Permalink to &quot;Agent 的经济性分析&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块一 · 01_基础概念 · 第 6 节 <strong>难度</strong>：⭐⭐ | <strong>前置知识</strong>：Agent 基础</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>构建大规模 Agent 系统的经济性</strong>是当前工业界的重大挑战。根据 Zylos Research 的报告，2025 年上半年企业 LLM 支出达到 84 亿美元，近 40% 的企业每年在语言模型上的花费超过 25 万美元。<a href="https://zylos.ai/research/2026-04-12-ai-agent-cost-optimization-token-budget-model-routing" target="_blank" rel="noreferrer">来源: Zylos Research - AI Agent Cost Optimization</a></p><p>Agent 单次用户请求可能触发 planning、tool selection、execution 等多步 LLM 调用，成本远超简单 chatbot。<a href="https://agentwiki.org/agent_cost_optimization" target="_blank" rel="noreferrer">来源: AI Agent Knowledge Base - Agent Cost Optimization</a></p><hr><h2 id="_2-成本结构分析" tabindex="-1">2. 成本结构分析 <a class="header-anchor" href="#_2-成本结构分析" aria-label="Permalink to &quot;2. 成本结构分析&quot;">​</a></h2><h3 id="_2-1-典型-agent-系统成本分布" tabindex="-1">2.1 典型 Agent 系统成本分布 <a class="header-anchor" href="#_2-1-典型-agent-系统成本分布" aria-label="Permalink to &quot;2.1 典型 Agent 系统成本分布&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>典型 Agent 系统成本构成:</span></span>
<span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│        Agent 系统成本构成      │</span></span>
<span class="line"><span>│                              │</span></span>
<span class="line"><span>│  LLM API 调用:    ████████░░ 70% |</span></span>
<span class="line"><span>│  工具调用/基础设施: ███░░░░░░░ 20% |</span></span>
<span class="line"><span>│  存储/监控/其他:   ██░░░░░░░░ 10% |</span></span>
<span class="line"><span>│                              │</span></span>
<span class="line"><span>│  其中每轮成本 = tokens × 单价  │</span></span>
<span class="line"><span>└──────────────────────────────┘</span></span></code></pre></div><h3 id="_2-2-各模型每百万-token-成本-2025-2026-参考" tabindex="-1">2.2 各模型每百万 Token 成本（2025-2026 参考） <a class="header-anchor" href="#_2-2-各模型每百万-token-成本-2025-2026-参考" aria-label="Permalink to &quot;2.2 各模型每百万 Token 成本（2025-2026 参考）&quot;">​</a></h3><p>| 模型 | 输入 | 输出 | 适用场景 | 每轮成本（2K in + 1K out） | |--|-|--|-|--|- | | <strong>GPT-4o-mini</strong> | $0.15 | $0.60 | 简单任务 | ~$0.0003 | | <strong>GPT-4o</strong> | $2.50 | $10.00 | 通用任务 | ~$0.005 | | <strong>Claude 3.5 Haiku</strong> | $0.25 | $1.25 | 简单任务 | ~$0.0005 | | <strong>Claude 3.5 Sonnet</strong> | $3.00 | $15.00 | 中等任务 | ~$0.003 | | <strong>Claude 3.5 Opus</strong> | $15.00 | $75.00 | 复杂推理 | ~$0.015 | | <strong>DeepSeek-R1</strong> | $0.50 | $2.00 | 开源替代 | ~$0.0006 | | <strong>本地 Llama 3.1</strong> | $0.00 | $0.00 | 自部署 | 仅 GPU 成本 |</p><hr><h2 id="_3-成本优化策略" tabindex="-1">3. 成本优化策略 <a class="header-anchor" href="#_3-成本优化策略" aria-label="Permalink to &quot;3. 成本优化策略&quot;">​</a></h2><h3 id="_3-1-模型分层策略-model-routing" tabindex="-1">3.1 模型分层策略（Model Routing） <a class="header-anchor" href="#_3-1-模型分层策略-model-routing" aria-label="Permalink to &quot;3.1 模型分层策略（Model Routing）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按任务复杂度分层:</span></span>
<span class="line"><span>┌──────────────────────────┐</span></span>
<span class="line"><span>│     模型分层架构          │</span></span>
<span class="line"><span>│                          │</span></span>
<span class="line"><span>│ L1（简单）→ GPT-4o-mini │  60-70% 的任务</span></span>
<span class="line"><span>│ L2（中等）→ Claude Sonnet│  20-30% 的任务</span></span>
<span class="line"><span>│ L3（复杂）→ GPT-4.5     │  5-10% 的任务</span></span>
<span class="line"><span>│ L4（推理）→ Claude Opus  │  &lt;5% 的任务</span></span>
<span class="line"><span>│                          │</span></span>
<span class="line"><span>│ 成本降低: 70-80%        │</span></span>
<span class="line"><span>└──────────────────────────┘</span></span></code></pre></div><p>OptyxStack 指出：&quot;最安全的低成本方案不是处处使用最小模型，而是在该特定场景下仍然能保证结果正确性的最小模型。&quot;<a href="https://optyxstack.com/cost-optimization/model-routing-for-cost-control-when-to-use-small-large-or-fallback-models" target="_blank" rel="noreferrer">来源: OptyxStack - Model Routing for Cost Control</a></p><h3 id="_3-2-缓存策略" tabindex="-1">3.2 缓存策略 <a class="header-anchor" href="#_3-2-缓存策略" aria-label="Permalink to &quot;3.2 缓存策略&quot;">​</a></h3><p>根据 AgentWiki，缓存是 Agent 成本优化中 ROI 最高的手段，可消除 20-45% 的 API 调用。<a href="https://agentwiki.org/caching_strategies_for_agents" target="_blank" rel="noreferrer">来源: AgentWiki - Caching Strategies for Agents</a></p><p>| 策略 | 说明 | 节省 | |--|-|--|- | | <strong>结果缓存</strong> | 相同输入直接返回 | 100% | | <strong>语义缓存</strong> | 相似输入使用缓存 | 30-50% | | <strong>Token 压缩</strong> | 摘要历史减少输入 | 50-80% |</p><h3 id="_3-3-小模型-vs-垂直模型-vs-通用大模型" tabindex="-1">3.3 小模型 vs 垂直模型 vs 通用大模型 <a class="header-anchor" href="#_3-3-小模型-vs-垂直模型-vs-通用大模型" aria-label="Permalink to &quot;3.3 小模型 vs 垂直模型 vs 通用大模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>成本/1M tokens</th><th>能力保留</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>通用大模型</strong></td><td>$2.50-20</td><td>100%</td><td>通用任务</td></tr><tr><td><strong>垂直小模型</strong></td><td>$0.00-0.20</td><td>85-95%</td><td>特定领域</td></tr><tr><td><strong>知识蒸馏</strong></td><td>$0.00-0.05</td><td>80-90%</td><td>大规模部署</td></tr><tr><td><strong>混合模型</strong></td><td>$0.30-1.00</td><td>90-95%</td><td>分层架构</td></tr></tbody></table><h3 id="_3-4-few-shot-提示优化" tabindex="-1">3.4 Few-shot 提示优化 <a class="header-anchor" href="#_3-4-few-shot-提示优化" aria-label="Permalink to &quot;3.4 Few-shot 提示优化&quot;">​</a></h3><p>Few-shot learning 可在保持同等效果的同时减少 20-40% 的 token 消耗。<a href="https://aitoolsbusiness.com/ai-cost-optimization/" target="_blank" rel="noreferrer">来源: AI Cost Optimization (AIToolsBusiness)</a></p><h3 id="_3-5-prompt-缓存" tabindex="-1">3.5 Prompt 缓存 <a class="header-anchor" href="#_3-5-prompt-缓存" aria-label="Permalink to &quot;3.5 Prompt 缓存&quot;">​</a></h3><p>企业环境中，prompt caching（复用系统 prompt 的 KV cache）可大幅降低重复请求成本。<a href="https://inductivee.com/blog/enterprise-llm-cost-optimization" target="_blank" rel="noreferrer">来源: Inductivee - LLM Cost Optimization</a></p><hr><h2 id="_4-roi-优化目标" tabindex="-1">4. ROI 优化目标 <a class="header-anchor" href="#_4-roi-优化目标" aria-label="Permalink to &quot;4. ROI 优化目标&quot;">​</a></h2><p>| 目标 | 策略 | 预期节省 | |--|-|--|- | | <strong>降低单次成本</strong> | 模型分层 + 缓存 | 70-80% | | <strong>提高任务完成率</strong> | 垂直模型 + 提示优化 | 10-20% | | <strong>减少人力投入</strong> | 自动化评测 + 监控 | 50-70% | | <strong>提高频率</strong> | 批量处理 + 异步 | 30-50% |</p><h3 id="典型场景成本估算" tabindex="-1">典型场景成本估算 <a class="header-anchor" href="#典型场景成本估算" aria-label="Permalink to &quot;典型场景成本估算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>月调用量</th><th>每轮成本</th><th>月成本</th></tr></thead><tbody><tr><td><strong>个人 Agent</strong></td><td>10K/月 × 1K tokens</td><td>$0.0005</td><td>~$5</td></tr><tr><td><strong>小团队</strong></td><td>100K/月 × 2K tokens</td><td>$0.003</td><td>~$300</td></tr><tr><td><strong>中型企业</strong></td><td>1M/月 × 3K tokens</td><td>$0.005</td><td>~$5,000</td></tr><tr><td><strong>大型企业</strong></td><td>10M/月 × 5K tokens</td><td>$0.008</td><td>~$40,000</td></tr><tr><td><strong>优化后（企业）</strong></td><td>10M/月 × 5K tokens</td><td>$0.001</td><td>~$5,000</td></tr><tr><td><strong>优化后（垂直模型）</strong></td><td>10M/月 × 5K tokens</td><td>$0.0001</td><td>~$500</td></tr></tbody></table><hr><h2 id="_5-最佳实践-checklist" tabindex="-1">5. 最佳实践 Checklist <a class="header-anchor" href="#_5-最佳实践-checklist" aria-label="Permalink to &quot;5. 最佳实践 Checklist&quot;">​</a></h2><ul><li>[ ] <strong>模型分层</strong> — 按任务复杂度选择不同模型</li><li>[ ] <strong>缓存优先</strong> — 相同输入不重复调用</li><li>[ ] <strong>垂直模型</strong> — 特定领域用垂直微调模型</li><li>[ ] <strong>提示优化</strong> — 精简提示词，用 Few-shot</li><li>[ ] <strong>异步批量</strong> — 合并相同任务</li><li>[ ] <strong>成本监控</strong> — 实时追踪每轮成本</li><li>[ ] <strong>定期审计</strong> — 每月分析成本构成</li></ul><hr><h2 id="_6-参考资料" tabindex="-1">6. 参考资料 <a class="header-anchor" href="#_6-参考资料" aria-label="Permalink to &quot;6. 参考资料&quot;">​</a></h2><ul><li><a href="https://callsphere.ai/blog/ai-agent-cost-optimization-strategies-production.md" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Strategies for Keeping Production Costs Under Control</a></li><li><a href="https://zylos.ai/research/2026-04-12-ai-agent-cost-optimization-token-budget-model-routing" target="_blank" rel="noreferrer">AI Agent Cost Optimization: Token Budgets, Model Routing, and Production FinOps (Zylos)</a></li><li><a href="https://optyxstack.com/cost-optimization/model-routing-for-cost-control-when-to-use-small-large-or-fallback-models" target="_blank" rel="noreferrer">Model Routing for Cost Control (OptyxStack)</a></li><li><a href="https://zylos.ai/research/2026-03-02-ai-agent-model-routing" target="_blank" rel="noreferrer">AI Agent Model Routing and Dynamic Model Selection (Zylos)</a></li><li><a href="https://harnessengineering.academy/blog/reducing-ai-agent-inference-costs-caching-strategies-model-routing-and-token-optimization-techniques/" target="_blank" rel="noreferrer">Reducing AI Agent Inference Costs (Harness Engineering)</a></li><li><a href="https://agentwiki.org/agent_cost_optimization" target="_blank" rel="noreferrer">Agent Cost Optimization (AgentWiki)</a></li><li><a href="https://agentwiki.org/caching_strategies_for_agents" target="_blank" rel="noreferrer">Caching Strategies for Agents (AgentWiki)</a></li><li><a href="https://aitoolsbusiness.com/ai-cost-optimization/" target="_blank" rel="noreferrer">AI Cost Optimization: Caching, Batching, Smaller Models</a></li><li><a href="https://www.agenticaipricing.com/the-pricing-implications-of-model-routing-and-fallback-logic/" target="_blank" rel="noreferrer">The pricing implications of model routing and fallback logic</a></li></ul>`,37)])])}const u=a(o,[["render",r]]);export{c as __pageData,u as default};
